import app from 'flarum/forum/app';
import stringToColor from 'flarum/common/utils/stringToColor';
import Link from 'flarum/common/components/Link';
import Avatar from 'flarum/common/components/Avatar';
import { ink } from './api';

/**
 * A board you look at (the editor draws its own): rows top to bottom, the
 * row's label in its colour, its items in order. Used by the list page and
 * by lists linked in posts, so it lives in forum.js and stays small.
 */

export function Tile({
  attrs
}) {
  return {
    view: ({
      attrs
    }) => {
      const {
        item
      } = attrs;
      return m("div", {
        className: 'TierTile' + (item.image ? ' TierTile--image' : ' TierTile--text'),
        title: item.label || undefined
      }, item.image ? m("img", {
        src: item.image,
        alt: item.label,
        loading: "lazy",
        decoding: "async",
        draggable: false
      }) : m("span", {
        className: "TierTile-text"
      }, item.label), attrs.badge);
    }
  };
}
export default function Board() {
  return {
    view: ({
      attrs
    }) => {
      const rowOf = attrs.rowOf || (item => item.tier);
      const rows = attrs.tiers.map(() => []);
      const pool = [];
      for (const item of attrs.items) {
        const row = rowOf(item);
        if (row === null || row === undefined || !rows[row]) pool.push(item);else rows[row].push(item);
      }
      return m("div", {
        className: 'TierBoard' + (attrs.compact ? ' TierBoard--compact' : '')
      }, attrs.tiers.map((tier, index) => m("div", {
        className: "TierBoard-row",
        key: index
      }, m("div", {
        className: "TierBoard-label",
        style: {
          background: tier.color,
          color: ink(tier.color)
        }
      }, m("span", null, tier.label)), m("div", {
        className: "TierBoard-items"
      }, rows[index].map(item => m(Tile, {
        key: item.key || item.label,
        item: item,
        badge: attrs.badge?.(item)
      }))))), attrs.pool && pool.length ? m("div", {
        className: "TierBoard-row TierBoard-row--pool"
      }, m("div", {
        className: "TierBoard-label TierBoard-label--pool"
      }, m("span", null, attrs.pool)), m("div", {
        className: "TierBoard-items"
      }, pool.map(item => m(Tile, {
        key: item.key || item.label,
        item: item
      })))) : null);
    }
  };
}

/** An avatar and a name linking to the member, or "a deleted member". */
export function Byline() {
  return {
    view: ({
      attrs
    }) => attrs.user ? m(Link, {
      className: "TierByline",
      href: app.route('user', {
        username: attrs.user.slug
      })
    }, m(Avatar, {
      user: avatarUser(attrs.user),
      className: "TierByline-avatar"
    }), m("span", {
      className: "TierByline-name"
    }, attrs.user.displayName)) : m("span", {
      className: "TierByline"
    }, attrs.fallback)
  };
}

/** Avatar wants a User model; these few methods are all it reads. */
export function avatarUser(user) {
  return {
    avatarUrl: () => user.avatarUrl,
    displayName: () => user.displayName,
    username: () => user.slug,
    color: () => '#' + stringToColor(user.displayName)
  };
}